import { waitForHealth } from './helpers';

const HEALTH_TIMEOUT_MS = 120_000;

interface ServiceDef {
  name: string;
  dir: string;
  port: number;
}

const SERVICES: ServiceDef[] = [
  { name: 'examples.IngestionService', dir: 'examples_ingestion_service', port: 8002 },
  { name: 'examples.OrderService', dir: 'examples_order_service', port: 8001 },
];

describe('Deployment Tests', () => {
  for (const svc of SERVICES) {
    it(`${svc.name} health check responds on port ${svc.port}`, async () => {
      const baseUrl = `http://localhost:${svc.port}`;
      const healthy = await waitForHealth(baseUrl, HEALTH_TIMEOUT_MS);
      expect(healthy).toBe(true);
    }, HEALTH_TIMEOUT_MS + 10_000);
  }
});
